// Ported from the Node app's Sequelize model FeeAdjustment (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class FeeAdjustmentConfiguration : IEntityTypeConfiguration<FeeAdjustment>
{
    public void Configure(EntityTypeBuilder<FeeAdjustment> builder)
    {
        builder.ToTable("fee_adjustments", t =>
        {
            t.HasCheckConstraint("CK_fee_adjustments_kind", "[kind] IN (N'discount', N'fine')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.FeeId).HasColumnName("fee_id");
        builder.Property(e => e.Kind).HasColumnName("kind").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Amount).HasColumnName("amount").HasColumnType("decimal(10,2)");
        builder.Property(e => e.Reason).HasColumnName("reason").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.CreatedBy).HasColumnName("created_by");
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasOne(e => e.Fee).WithMany(p => p.FeeAdjustments).HasForeignKey(e => e.FeeId).OnDelete(DeleteBehavior.NoAction);
    }
}
